import pytest

from moonraker.components.file_manager.metadata import (
    READ_SIZE,
    BaseSlicer,
    BioSlicer,
    PrusaSlicer,
)

HEADER = (
    "; generated by BioSlicer 3.0.0+dev.20260708 on 2026-09-24 at 20:34:41 UTC\n"
    "\n"
    "SET_GCODE_VARIABLE MACRO=BIOSLICER_PROCESS_PARAMS VARIABLE=bed_temp VALUE=55\n"
)
BODY = (
    "SET_PRINT_STATS_INFO TOTAL_LAYER=2\n"
    "PRINT_START\n"
    "G21 ; set units to millimeters\n"
    "G1 Z.2 F7800\n"
    "G1 Z.4\n"
    "PRINT_END\n"
    "; total layers count = 2\n"
)


def video_block(name: str, size: int) -> str:
    line = "; bioslicer_sla_video " + "A" * 76 + "\n"
    return (
        f"; bioslicer_sla_video begin name={name} extruder=4 bytes={size}\n"
        + line * (size // len(line) + 1)
        + f"; bioslicer_sla_video end name={name}\n"
    )


def write_gcode(tmp_path, content: str):
    path = tmp_path / "print.gcode"
    path.write_bytes(content.encode())
    return path


@pytest.mark.parametrize("video_size", [1024, READ_SIZE * 3])
def test_bioslicer_start_byte_follows_embedded_video(tmp_path, video_size):
    content = HEADER + video_block("sla_t4", video_size) + BODY
    path = write_gcode(tmp_path, content)

    slicer = BaseSlicer.from_file(str(path))

    assert isinstance(slicer, BioSlicer)
    assert slicer.slicer_name == "BioSlicer"
    assert slicer.slicer_version == "3.0.0+dev.20260708"
    assert slicer.parse_gcode_start_byte() == content.index("\nG21")
    assert slicer.parse_gcode_end_byte() == content.index("PRINT_END")


def test_bioslicer_start_byte_follows_last_embedded_video(tmp_path):
    content = (
        HEADER
        + video_block("sla_t4", 1024)
        + "M73 P0 R10\n"
        + video_block("sla_t5", 1024)
        + BODY
    )
    path = write_gcode(tmp_path, content)

    slicer = BaseSlicer.from_file(str(path))

    assert slicer.parse_gcode_start_byte() == content.index("\nG21")


def test_bioslicer_start_byte_without_video(tmp_path):
    content = HEADER + BODY
    path = write_gcode(tmp_path, content)

    slicer = BaseSlicer.from_file(str(path))

    assert isinstance(slicer, BioSlicer)
    assert slicer.parse_gcode_start_byte() == content.index("\nG21")


def test_bioslicer_start_byte_missing_after_video(tmp_path):
    content = HEADER + video_block("sla_t4", 1024) + "PRINT_END\n"
    path = write_gcode(tmp_path, content)

    slicer = BaseSlicer.from_file(str(path))

    assert slicer.parse_gcode_start_byte() is None


def test_prusaslicer_fork_is_not_identified_as_bioslicer(tmp_path):
    content = HEADER.replace("BioSlicer 3.0.0+dev.20260708", "OrcaSlicer 2.1.0") + BODY
    path = write_gcode(tmp_path, content)

    slicer = BaseSlicer.from_file(str(path))

    assert type(slicer) is PrusaSlicer
    assert slicer.slicer_name == "OrcaSlicer"
